    .req_enable (req_enable),

    .dest_clk (dest_clk),
    .dest_ext_resetn (dest_ext_resetn),
    .dest_resetn (dest_resetn),
    .dest_enable (dest_enable),
    .dest_enabled (dest_enabled),

