  function compare_id;
    input [ID_WIDTH-1:0] a;
    input [ID_WIDTH-1:0] b;
    begin
      compare_id = a[ID_WIDTH-1] == b[ID_WIDTH-1];
      if (ID_WIDTH >= 2) begin
        if (a[ID_WIDTH-2] == b[ID_WIDTH-2]) begin
          compare_id = 1'b1;
        end
      end
      if (ID_WIDTH >= 3) begin
        if (a[ID_WIDTH-3:0] != b[ID_WIDTH-3:0]) begin
          compare_id = 1'b1;
        end
      end
    end
